script.code:
//refAssemblies: System.Diagnostics.Process.dll
using System;
using System.Diagnostics;
using System.IO;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// The server refuses to start without server_packages.sii/.dat ("Server packages file not found"), which only the
// game client can export (export_server_packages). Write a base-map pair when there is none, so a new server starts;
// a customer who wants DLC maps or mods uploads their own export over it.
var root = (string)ThisService.RootDirectory;
var home = Path.Combine(root, "Euro Truck Simulator 2");
Directory.CreateDirectory(home);
void Ensure(string name, string base64)
{
    var path = Path.Combine(home, name);
    if (File.Exists(path)) return;
    File.WriteAllBytes(path, Convert.FromBase64String(base64));
    ScriptConsole.WriteLine((object)("Created a default " + name + " (base map, no DLC)."));
}
Ensure("server_packages.sii", "");
Ensure("server_packages.dat", "");

// The panel writes server_config.sii only when the service is created, reinstalled or moved: after an IP/port change
// in the service settings the file still holds the old ports. Put the assigned ports back on every start.
var config = Path.Combine(home, "server_config.sii");
if (File.Exists(config))
{
    var text = File.ReadAllText(config);
    var updated = System.Text.RegularExpressions.Regex.Replace(text, @"(?m)^(\s*connection_dedicated_port\s*:\s*)\d+", "${1}" + ThisService.GamePort);
    updated = System.Text.RegularExpressions.Regex.Replace(updated, @"(?m)^(\s*query_dedicated_port\s*:\s*)\d+", "${1}" + ThisService.QueryPort);
    if (updated != text)
    {
        File.WriteAllText(config, updated);
        ScriptConsole.WriteLine((object)("server_config.sii: ports set to " + ThisService.GamePort + " / " + ThisService.QueryPort + "."));
    }
}

// Linux: the Steam API looks for steamclient.so in ~/.steam/sdk64 (the service root is the home directory).
if (System.OperatingSystem.IsLinux())
{
    var source = Path.Combine(root, "linux64", "steamclient.so");
    var target = Path.Combine(root, ".steam", "sdk64", "steamclient.so");
    if (File.Exists(source) && (!File.Exists(target) || new FileInfo(target).Length != new FileInfo(source).Length))
    {
        Directory.CreateDirectory(Path.GetDirectoryName(target));
        File.Copy(source, target, true);
        ScriptConsole.WriteLine((object)"Copied steamclient.so to .steam/sdk64.");
    }

    // The server binary links libatomic.so.1, which minimal distributions do not install (exit code 127 without it).
    var server = Path.Combine(root, "bin", "linux_x64", "eurotrucks2_server");
    if (Shell("ldd '" + server + "' | grep -q 'libatomic.so.1 => not found'", out _))
    {
        ScriptConsole.WriteLine((object)"libatomic.so.1 is missing on this host; installing it.");
        var installed =
            Shell("command -v apt-get && (DEBIAN_FRONTEND=noninteractive apt-get install -y libatomic1 || (apt-get update && DEBIAN_FRONTEND=noninteractive apt-get install -y libatomic1))", out var aptLog)
            || Shell("command -v dnf && dnf install -y libatomic", out _)
            || Shell("command -v yum && yum install -y libatomic", out _)
            || Shell("command -v zypper && zypper --non-interactive install libatomic1", out _);
        if (!installed)
        {
            throw new Exception("libatomic.so.1 is missing and could not be installed. Install the libatomic1 (Debian/Ubuntu) or libatomic (RHEL) package on this host. " + aptLog);
        }
        ScriptConsole.WriteLine((object)"Installed libatomic.");
    }
}

bool Shell(string command, out string output)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", command }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        output = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}
